files.content:
:root {
  --bg: #1b1f2a;
  --card: #262c3a;
  --accent: #4f8cff;
  --accent-press: #3a6fd8;
  --text: #e8edf7;
  --muted: #8a93a8;
  --danger: #ff5c72;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image: linear-gradient(135deg, #1b1f2a 0%, #232a3a 100%);
  font-family: ui-monospace, "Courier New", monospace;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 440px;
  background: var(--card);
  border: 2px solid #333b4d;
  border-radius: 10px;
  padding: 24px;
  box-shadow: 0 8px 0 #12151d, 0 12px 30px rgba(0,0,0,.4);
}

h1 { margin: 0; font-size: 24px; letter-spacing: 1px; }
.subtitle { margin: 4px 0 20px; color: var(--muted); font-size: 14px; }

.stats { display: flex; gap: 12px; margin-bottom: 20px; }
.stat {
  flex: 1;
  background: #1f2532;
  border: 2px solid #333b4d;
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.stat-label { color: var(--muted); font-size: 14px; }
.stat-value { font-size: 20px; font-weight: 700; color: var(--accent); }

.input-row { display: flex; gap: 10px; margin-bottom: 20px; }
#todo-input {
  flex: 1;
  min-width: 0;
  padding: 12px;
  font: inherit;
  color: var(--text);
  background: #1f2532;
  border: 2px solid #333b4d;
  border-radius: 8px;
}
#todo-input:focus { outline: none; border-color: var(--accent); }

button {
  font: inherit;
  cursor: pointer;
  border: 2px solid transparent;
  border-radius: 8px;
  transition: transform .05s, background .15s;
}

#todo-add {
  padding: 12px 18px;
  background: var(--accent);
  color: #fff;
  font-weight: 700;
}
#todo-add:hover { background: #6a9dff; }
#todo-add:active { background: var(--accent-press); transform: translateY(1px); }

.todo-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #1f2532;
  border: 2px solid #333b4d;
  border-radius: 8px;
  padding: 10px 12px;
}

.todo-item input[type="checkbox"] {
  width: 20px; height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.todo-text { flex: 1; word-break: break-word; }
.todo-item.done .todo-text { text-decoration: line-through; color: var(--muted); }

.todo-delete {
  background: transparent;
  color: var(--danger);
  border-color: #3a2a30;
  padding: 6px 10px;
  font-size: 14px;
}
.todo-delete:hover { background: rgba(255,92,114,.15); }
.todo-delete:active { transform: translateY(1px); }

.empty { color: var(--muted); text-align: center; font-size: 14px; margin: 8px 0 0; }

button:focus-visible, input:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); border: 0;
}

@media (max-width: 400px) {
  .card { padding: 18px; }
  .input-row { flex-direction: column; }
}

(function () {
  "use strict";

  var input = document.getElementById("todo-input");
  var addBtn = document.getElementById("todo-add");
  var form = document.getElementById("todo-form");
  var list = document.getElementById("todo-list");
  var totalEl = document.getElementById("todo-total");
  var remainingEl = document.getElementById("remaining");
  var emptyEl = document.getElementById("empty");

  var nextId = 1;
  var tasks = [];

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    var rem = 0;
    for (var i = 0; i < tasks.length; i++) {
      if (!tasks[i].done) rem++;
    }
    remainingEl.textContent = String(rem);
    emptyEl.hidden = tasks.length !== 0;
  }

  function makeItem(task) {
    var li = document.createElement("li");
    li.className = "todo-item" + (task.done ? " done" : "");
    li.dataset.id = String(task.id);

    var cb = document.createElement("input");
    cb.type = "checkbox";
    cb.id = "todo-check-" + task.id;
    cb.checked = task.done;
    cb.setAttribute("aria-label", "Mark task done");
    cb.addEventListener("change", function () {
      task.done = cb.checked;
      li.classList.toggle("done", task.done);
      updateCounts();
    });

    var span = document.createElement("span");
    span.className = "todo-text";
    span.id = "todo-text-" + task.id;
    span.textContent = task.text;

    var del = document.createElement("button");
    del.type = "button";
    del.className = "todo-delete";
    del.id = "todo-delete-" + task.id;
    del.textContent = "Delete";
    del.setAttribute("aria-label", "Delete task");
    del.addEventListener("click", function () {
      var idx = tasks.indexOf(task);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.appendChild(cb);
    li.appendChild(span);
    li.appendChild(del);
    return li;
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) { input.value = ""; return; }
    var task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    list.appendChild(makeItem(task));
    input.value = "";
    input.focus();
    updateCounts();
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    addTask();
  });
  addBtn.addEventListener("click", function (e) {
    e.preventDefault();
    addTask();
  });

  updateCounts();
})();
